import unittest

class Test(unittest.TestCase):
    def test_cycles_through_servers(self):
        b = RoundRobinBalancer(['a', 'b', 'c'])
        result = [b.next() for _ in range(5)]
        self.assertEqual(result, ['a', 'b', 'c', 'a', 'b'])
    def test_single_server(self):
        b = RoundRobinBalancer(['only'])
        self.assertEqual(b.next(), 'only')
        self.assertEqual(b.next(), 'only')
    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            RoundRobinBalancer([])

if __name__ == '__main__':
    unittest.main()
